// Stats JSON is generated by `python -m museum stats` into src/data/ before every build.
import metaJson from '../data/meta.json';
import lobbyJson from '../data/lobby.json';
import recordsJson from '../data/records.json';
import shameJson from '../data/shame.json';
import managersJson from '../data/managers.json';
import rivalriesJson from '../data/rivalries.json';
import championsJson from '../data/champions.json';
import archivesJson from '../data/archives.json';

export const meta: any = metaJson;
export const lobby: any = lobbyJson;
export const records: any[] = recordsJson as any[];
export const shame: any[] = shameJson as any[];
export const managers: any[] = managersJson as any[];
export const rivalries: Record<string, any> = rivalriesJson as any;
export const champions: any = championsJson;
export const archives: any[] = archivesJson as any[];

const byId = new Map<string, any>(meta.managers.map((m: any) => [m.id, m]));

export function mgr(id: string | null | undefined) {
  return (id && byId.get(id)) || { id, name: id || 'Unknown', color: '#6b7280', initials: '?' };
}

export const name = (id: string | null | undefined) => mgr(id).name;

const base = import.meta.env.BASE_URL.replace(/\/?$/, '/');

/** Site-relative URL honoring the GitHub Pages base path. */
export function url(path = '') {
  const clean = path.replace(/^\//, '');
  if (!clean) return base;
  const [p, hash] = clean.split('#');
  const withSlash = p === '' || p.endsWith('/') || p.includes('.') ? p : `${p}/`;
  return base + withSlash + (hash ? `#${hash}` : '');
}

export const pairKey = (a: string, b: string) => [a, b].sort().join('--');

export function fmt(n: number | null | undefined, digits = 2) {
  if (n === null || n === undefined) return '—';
  return n.toLocaleString('en-US', { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

export const latestLabel = `Week ${meta.latest.week}, ${meta.latest.season}`;

export function ordinal(n: number) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

export const recordStr = (w: number, l: number, t = 0) => `${w}-${l}${t ? `-${t}` : ''}`;
